const cloneState = (state: WorldStateHandle): WorldStateHandle => ({
  zef: state.zef,
});

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return { zef: "nim" };
  },

  applyOperation(state, operationDisplayName) {
    if (operationDisplayName === "advanceZef") {
      if (state.zef !== "nim") {
        return { success: false, error: "advanceZef can only be applied when Zef is nim" };
      }

      return { success: true, newState: { zef: "pex" } };
    }

    if (operationDisplayName === "resetZef") {
      if (state.zef !== "pex") {
        return { success: false, error: "resetZef can only be applied when Zef is pex" };
      }

      return { success: true, newState: { zef: "nim" } };
    }

    return { success: false, error: `Unknown operation: ${operationDisplayName}` };
  },

  getEntityState(state, entityDisplayName) {
    return entityDisplayName === "Zef" ? state.zef : "unknown";
  },

  toAbstractSnapshot(state) {
    const snapshot = cloneState(state);
    return { Zef: snapshot.zef };
  },
};
